#!/usr/bin/env python3
"""
Round 157k (culprits), 4 October 2026. Needs round 156k.

Removes the seventh basemap (154k-156k) altogether.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 157k (4 October)\n\nNeeds round 156k. No tiles patch. No app.js?v= bump.\n\n- The owner: remove the seventh basemap (Pen and ink / Black and white,\n  rounds 154k-156k) altogether. Its whole block is gone from app.js (layers\n  outline-ink-*, inkdraw://, inkDrawSquare, inkPattern, the menu entry and\n  its wrappers of basemapPanelHtml and setBasemap); its tests are replaced by\n  one check that nothing of it is left. The chosen basemap is not remembered\n  between visits, so nobody is left on it. The notes for 154k-156k below\n  stay as history only.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round157k: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 156k" not in h.read_text(encoding="utf-8"):
        sys.exit("round157k: round 156k must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round157k: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round157k: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round157k: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
